"""Usage: python3 numcheck.py <ID>  -- checks numbers in draft text fields against text/<ID>.txt"""
import json, re, sys, os
base = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
i = sys.argv[1]
d = json.load(open(f"{base}/drafts/{i}.json"))
t = open(f"{base}/text/{i}.txt").read()
tn = re.sub(r"\s+", " ", t)
fields = {k: d.get(k) for k in ["evidenceSummary", "screeningLimitations", "synthesisCaution"]}
fields.update({f"paper.{k}": v for k, v in (d.get("paper") or {}).items() if isinstance(v, str)})
seen = set()
for f, v in fields.items():
    if not v:
        continue
    if "—" in v:
        print(f"EMDASH in {f}")
    for n in re.findall(r"\d[\d,]*\.?\d*", v):
        n = n.rstrip(".,")
        if n in seen or len(n) < 2 and n not in "0":
            continue
        seen.add(n)
        variants = {n, n.replace(",", ""), n.replace(",", " ")}
        hits = []
        for var in variants:
            for m in re.finditer(r"(?<![\d.])" + re.escape(var) + r"(?![\d])", tn):
                hits.append(tn[max(0, m.start() - 60): m.end() + 40])
        status = "HIT " if hits else "MISS"
        print(f"{status} {n} [{f}]" + (f" :: {hits[0]!r}" if hits else ""))

